style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: transparent !important;
    min-height: 100vh !important;
  }

  html::before,
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: url("https://cdn.discordapp.com/attachments/1263232071527305376/1436867874512961546/download.gif") center / cover no-repeat fixed;
    z-index: -1;
    opacity: 0.9;
    pointer-events: none;
  }

  header, nav, footer,
  .container, .content, .page-content, .app, .rbx-body, .rbx-header,
  .rbx-page-content, .rbx-tabs, .rbx-upgrade, .profile-header, .section,
  .card, .card-item, .game-card, .profile-avatar,
  .container-main, .content-settings {
    background: rgba(0,0,0,0.4) !important;
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
  }

  .card, .section, .game-card {
    border-radius: 12px !important;
  }
}
